import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { openaiUrl } from "./openai";

/**
 * Speech-to-text provider.
 *  - OPENAI_API_KEY set  -> OpenAI transcription (multilingual incl. Yoruba / Hausa)
 *  - otherwise           -> the bundled sample recordings are recognised by SHA-256
 *                           (public/assets/audio/manifest.json, generated by scripts/seed.ts)
 */
export interface Transcription {
  text: string;
  engine: "openai" | "sample";
}

export async function transcribe(audio: Buffer, filename: string, mime: string): Promise<Transcription> {
  if (process.env.OPENAI_API_KEY) {
    const form = new FormData();
    form.set("file", new Blob([new Uint8Array(audio)], { type: mime }), filename);
    form.set("model", "whisper-1");
    const res = await fetch(openaiUrl("/audio/transcriptions"), {
      method: "POST",
      headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
      body: form,
    });
    if (!res.ok) {
      console.error(`OpenAI transcription failed: ${res.status}`);
      throw new Error("Transcription is unavailable right now. Paste the announcement text instead.");
    }
    const json = (await res.json()) as { text: string };
    return { text: json.text, engine: "openai" };
  }
  const hash = createHash("sha256").update(audio).digest("hex");
  try {
    const manifest = JSON.parse(
      await readFile(path.join(process.cwd(), "public/assets/audio/manifest.json"), "utf8"),
    ) as Record<string, { transcript: string }>;
    const hit = manifest[hash];
    if (hit) return { text: hit.transcript, engine: "sample" };
  } catch {
    /* no manifest */
  }
  throw new Error(
    "This audio could not be transcribed. Paste the announcement text instead.",
  );
}
